input.sql:
select count(*), count(distinct account_id), count(distinct as_of_date), min(as_of_date), max(as_of_date) from main_mart.dim_account;
select plan_type, count(*) from main_mart.dim_account group by 1 order by 2 desc;
select currency, is_finalized, is_latest_snapshot, count(*), min(revenue_month), max(revenue_month), sum(revenue_amount) from main_mart.fct_revenue group by all order by all;
select count(*) from main_mart.fct_revenue r left join main_mart.dim_account a using(account_id) where a.account_id is null;
select count(*), count(distinct (account_id, revenue_month)) from main_mart.fct_revenue where is_latest_snapshot;

select r.account_id, r.revenue_month, r.revenue_amount, r.currency, r.is_latest_snapshot from main_mart.fct_revenue r left join main_mart.dim_account a using(account_id) where a.account_id is null;
select r.account_id, a.plan_type, r.revenue_month, r.revenue_amount, r.is_finalized from main_mart.fct_revenue r left join main_mart.dim_account a using(account_id) where currency='USD' and is_latest_snapshot order by 1,3;
select a.plan_type, a.status, count(distinct a.account_id) accts, count(r.account_id) rows_, count(distinct r.account_id) rev_accts from main_mart.dim_account a left join main_mart.fct_revenue r on r.account_id=a.account_id and r.is_latest_snapshot group by all order by all;

select coalesce(a.plan_type,'(マスタ未登録)') plan, r.currency, count(distinct r.account_id) accts, sum(r.revenue_amount) total, round(sum(r.revenue_amount)/count(distinct r.account_id)) per_acct, sum(case when r.is_zero_revenue then 1 else 0 end) zero_rows, count(*) rows_
from main_mart.fct_revenue r left join main_mart.dim_account a using(account_id)
where r.is_latest_snapshot and r.is_finalized group by all order by 2,4 desc;
select coalesce(a.plan_type,'(マスタ未登録)') plan, r.currency, count(distinct r.account_id) accts, sum(r.revenue_amount) total
from main_mart.fct_revenue r left join main_mart.dim_account a using(account_id)
where r.is_latest_snapshot and not r.is_finalized group by all order by 2,4 desc;
select a.plan_type, r.revenue_month, sum(r.revenue_amount) from main_mart.fct_revenue r join main_mart.dim_account a using(account_id) where r.is_latest_snapshot and r.currency='JPY' group by all order by 1,2;
